"""Cousins in Binary Tree — record each value's depth and parent.

Time: O(n)   Space: O(h)
"""
if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def isCousins(self, root, x: int, y: int) -> bool:
        found = {}

        def walk(node, parent, depth) -> None:
            if not node:
                return
            if node.val in (x, y):
                found[node.val] = (parent, depth)
            walk(node.left, node.val, depth + 1)
            walk(node.right, node.val, depth + 1)

        walk(root, None, 0)
        if x not in found or y not in found:
            return False
        (px, dx), (py, dy) = found[x], found[y]
        return dx == dy and px != py
